insert into public.site_settings (id, data) values (1, '{"admissions_phone":"+6019 999 9070","admissions_email":"info@imas.edu.my","enquiry_subject":"Canadian Diploma enquiry","website_selangor":"https://imas.edu.my/","website_kl":"https://kl.imas.edu.my/","ielts_min_band":6,"ca_weight":60,"exam_weight":40,"pass_mark":60,"attendance_min":90,"total_credit_hours":100,"grade12_credit_hours":24,"hero_title":"Your Canadian high school diploma, earned at IMAS.","hero_lede":"IMAS is the first school in Malaysia accredited by New Brunswick, Canada. Our students graduate with the same diploma as students in Canada, without leaving home.","current_academic_year":"","repeat_threshold":3,"feedback_required":true}'::jsonb) on conflict (id) do nothing;
insert into public.courses (credit_hours, id, name, code, cluster, kind, description, sort) values
  (4, 'arabic-110', 'Additional Language (Arabic)', '110', 'language-arts', 'nb', 'Builds communication in Arabic across listening, speaking, reading and writing. This is the Additional Language course in the diploma.', 10),
  (4, 'ela-f10', 'English Language Arts Foundational', '10', 'language-arts', 'nb', 'Reading, writing, speaking and listening across literary and informational texts. The foundation for English in Grades 11 and 12.', 20),
  (4, 'ela-f11', 'English Language Arts Foundational', '11', 'language-arts', 'nb', 'Critical reading, analytical writing and oral communication with longer and more complex texts.', 30),
  (4, 'ela-12', 'English Language Arts', '12', 'language-arts', 'nb', 'The Grade 12 English course: critical analysis, research and extended writing that prepare you for university study.', 40),
  (4, 'writing-110', 'Writing', '110', 'language-arts', 'nb', 'Writing for different purposes and audiences, from argument to narrative, with drafting, feedback and revision.', 50),
  (4, 'reading-tutor-120', 'Reading Tutor', '120', 'language-arts', 'nb', 'You learn evidence-based reading strategies and tutor younger learners in literacy, building communication, empathy and leadership.', 60),
  (4, 'civics', 'Civics', '', 'humanities', 'nb', 'How government, law and citizenship work, and how citizens take part in public life.', 70),
  (4, 'world-issues-120', 'World Issues', '120', 'humanities', 'nb', 'Global challenges such as human rights, inequality and the environment, examined through evidence and different perspectives.', 80),
  (4, 'economics-120', 'Economics', '120', 'humanities', 'nb', 'Markets, supply and demand, government policy and the global economy.', 90),
  (4, 'biology-111', 'Biology', '111/2', 'sciences', 'nb', 'Cells, genetics, ecology and human body systems, with laboratory investigation.', 100),
  (4, 'chemistry-111', 'Chemistry', '111/2', 'sciences', 'nb', 'Matter, chemical reactions and quantitative chemistry, with laboratory work.', 110),
  (4, 'physics-111', 'Physics', '111/2', 'sciences', 'nb', 'Motion, forces, energy and waves, applied through experiments and problem solving.', 120),
  (4, 'human-physiology', 'Human Physiology', '', 'sciences', 'nb', 'How the systems of the human body work together to keep us healthy.', 130),
  (4, 'sss-10', 'Science for Sustainable Society', '10', 'sciences', 'nb', 'Scientific inquiry applied to sustainability: ecosystems, climate, human impact and practical solutions to environmental problems.', 140),
  (4, 'nrf-10', 'Numbers, Relations, and Functions', '10', 'mathematics', 'nb', 'Number, relations, linear functions and systems: the algebra that later mathematics builds on.', 150),
  (4, 'precalc-110', 'Pre-Calculus', '110', 'mathematics', 'nb', 'Functions, trigonometry and algebraic reasoning that lead into Pre-Calculus A 120.', 160),
  (4, 'precalc-a-120', 'Pre-Calculus A', '120', 'mathematics', 'nb', 'Grade 12 pre-calculus: advanced functions and trigonometry, laying the groundwork for university calculus.', 170),
  (4, 'graphic-art-110', 'Graphic Art and Design', '110', 'creative-arts', 'nb', 'Visual communication through design principles, typography, image-making and digital tools.', 180),
  (4, 'psychology-110', 'Psychology', '110', 'wellness', 'nb', 'How people think, learn, feel and behave, and how psychologists study the mind.', 190),
  (4, 'kinesiology-120', 'Introduction to Kinesiology', '120', 'wellness', 'nb', 'The science of human movement: anatomy, biomechanics, fitness and health.', 200),
  (4, 'career-pathway-design', 'Career Pathway Design', '', 'career', 'nb', 'Explore careers and further study, and build the personalised Career Life Plan you need to graduate.', 210),
  (4, 'entrepreneurship-120', 'Entrepreneurship', '120', 'career', 'nb', 'Generating and testing business ideas, planning a venture, and the habits of successful entrepreneurs.', 220),
  (4, 'cybersecurity-120', 'Cyber Security', '120', 'career', 'nb', 'Protecting systems and data: threats, defences, networks and responsible digital practice.', 230),
  (4, 'computer-science-110', 'Computer Science', '110', 'career', 'nb', 'Computational thinking and programming: algorithms, data and building software solutions.', 240),
  (4, 'business-management-120', 'Business Management', '120', 'career', 'nb', 'How organisations are run: management, marketing, operations and decision-making.', 250),
  (4, 'financial-accounting-120', 'Financial Accounting', '120', 'career', 'nb', 'Recording, reporting and interpreting the financial information of a business.', 260),
  (0, 'islamiyat', 'Islamiyat', '', 'school', 'school', 'IMAS school course in Islamic studies, taken alongside the diploma courses in Grade 10.', 270),
  (0, 'prep-kinesiology', 'Introduction to Kinesiology – Prep', '', 'prep', 'prep', 'Prepares you for Introduction to Kinesiology 120 in Grade 12.', 280),
  (0, 'prep-psychology', 'Psychology – Prep', '', 'prep', 'prep', 'Prepares you for Psychology 110 in Grade 12.', 290),
  (0, 'prep-civics', 'Civics – Prep', '', 'prep', 'prep', 'Prepares you for Civics in Grade 12.', 300),
  (0, 'prep-world-issues', 'World Issues – Prep', '', 'prep', 'prep', 'Prepares you for World Issues 120 in Grade 12.', 310),
  (0, 'prep-visual-arts', 'Visual Arts 10 – Prep', '', 'prep', 'prep', 'Prepares you for Graphic Art and Design 110 in Grade 12.', 320),
  (0, 'prep-mathematics', 'Mathematics – Prep', '', 'prep', 'prep', 'Prepares you for Pre-Calculus A 120 in Grade 12.', 330),
  (0, 'prep-english', 'English – Prep', '', 'prep', 'prep', 'Prepares you for English Language Arts 12 in Grade 12.', 340)
insert into public.tracks (id, name, stream, focus, entry_grade, duration_years, stated_total, summary, sort) values
  ('can-g10', 'CAN · Grade 10 entry', 'CAN', null, 10, 3, 21, 'The full three-year Canadian programme, Grade 10 to Grade 12, following the New Brunswick curriculum only.', 10),
  ('can-g11', 'CAN · Grade 11 entry', 'CAN', null, 11, 2, 19, 'A two-year route that joins in Grade 11. The Grade 10 foundation courses are taken alongside the Grade 11 courses.', 20),
  ('cad-sci-g10', 'Dual Program · Science · Grade 10 entry', 'CAD', 'science', 10, 3, 21, 'Cambridge IGCSE (Science stream) in Grades 10 and 11 with Canadian courses alongside, then the Canadian Grade 12 year. Two certificates.', 30),
  ('cad-com-g10', 'Dual Program · Commerce · Grade 10 entry', 'CAD', 'commerce', 10, 3, 22, 'Cambridge IGCSE (Commerce stream) in Grades 10 and 11 with Canadian courses alongside, then the Canadian Grade 12 year. Two certificates.', 40),
  ('cad-sci-g11', 'Dual Program · Science · Grade 11 entry', 'CAD', 'science', 11, 2, 19, 'Cambridge IGCSE (Science stream) in Grade 11 with Canadian courses alongside, then the Canadian Grade 12 year. Two certificates.', 50),
  ('cad-com-g11', 'Dual Program · Commerce · Grade 11 entry', 'CAD', 'commerce', 11, 2, 21, 'Cambridge IGCSE (Commerce stream) in Grade 11 with Canadian courses alongside, then the Canadian Grade 12 year. Two certificates.', 60)
