insert into public.partners (id, name, location, website, figure, figure_label, summary, highlights, eligibility_note, contact_email, image_url, image_credit, sort, published) values
  ('st-thomas', 'St. Thomas University', 'Fredericton, New Brunswick', 'https://www.stu.ca', '≈ CA$45,000', 'tuition discount over a four-year degree', 'STU charges graduates of accredited New Brunswick offshore schools a discounted tuition rate for every year of an undergraduate degree.', array['Discounted tuition for all four years of study', 'Entrance scholarships from CA$500 to CA$100,000', 'Take STU courses while in Grade 12 at the domestic rate (Advanced Standing), with starts in January, May and September', 'Free application for students who tour the campus, virtually or in person', 'Average class size of 23 students in Fredericton, the capital of New Brunswick']::text[], '', 'admissions@stu.ca', '', '', 10, true),
  ('mount-allison', 'Mount Allison University', 'Sackville, New Brunswick', 'https://mta.ca', '≈ CA$20,000', 'saved through domestic tuition in years one and two', 'Through the NB Advantage Global Program, Mount Allison charges New Brunswick offshore graduates domestic tuition for the first two years of their degree.', array['Domestic tuition fees for the first two years', 'Scholarships from CA$4,000 to CA$56,000, plus bursaries and campus jobs', 'English proficiency test waived with strong results in English 121 or 122', 'More than 50 programmes across arts, science, commerce, fine arts and music', 'Ranked Canada’s top primarily undergraduate university by Maclean’s more often than any other']::text[], '', 'admissions@mta.ca', '', '', 20, true),
  ('saint-marys', 'Saint Mary’s University', 'Halifax, Nova Scotia', 'https://www.smu.ca', 'CA$1,000', 'off every 3-credit course (≈ CA$40,000 over a degree)', 'An AEI partner university offering tuition reductions to graduates of the New Brunswick programme, subject to its eligibility requirements.', array['Tuition reduction on every 3-credit course for the whole undergraduate degree', 'Estimated total saving of about CA$40,000', 'Located in Halifax, the largest city in Atlantic Canada']::text[], 'Saint Mary’s publishes this reduction for New Brunswick programme graduates. Confirm eligibility for offshore-school graduates with its admissions office before applying.', '', '', '', 30, true)
insert into public.faqs (id, audience, question, answer, sort, published) values
  ('what-is', 'new', 'What is the Canadian Diploma at IMAS?', 'It is the official New Brunswick High School Diploma from Canada, taught at IMAS. Graduates receive the same diploma as students in New Brunswick, signed by the province’s Minister of Education.', 10, true),
  ('where-in-malaysia', 'new', 'Where can I study for a Canadian high school diploma in Malaysia?', 'At IMAS International School. IMAS teaches the official New Brunswick (Canada) High School Diploma and is the first school in Malaysia accredited by New Brunswick. You study the New Brunswick curriculum at IMAS and graduate with the same diploma as students in Canada.', 20, true),
  ('recognised-malaysia', 'new', 'Is the diploma recognised in Malaysia?', 'Yes. The programme is approved by the Ministry of Education Malaysia, and the New Brunswick High School Graduation Diploma is listed by the Malaysian Qualifications Agency (MQA) as an entry qualification for bachelor’s degree programmes.', 30, true),
  ('accreditation', 'new', 'Who accredits the Canadian Diploma at IMAS?', 'The Province of New Brunswick, through Atlantic Education International (AEI), its government-owned agency that accredits schools around the world to teach the New Brunswick curriculum. AEI inspects the programme at IMAS every year.', 40, true),
  ('can-vs-cad', 'new', 'What is the difference between CAN and the Dual Program (CAD)?', 'CAN students follow the Canadian curriculum only. Dual Program (CAD) students also take Cambridge IGCSE examinations, so they finish with two certificates: the IGCSE and the New Brunswick High School Diploma.', 50, true),
  ('igcse-and-canadian', 'new', 'Can I take the IGCSE and a Canadian diploma together?', 'Yes, in the Dual Program (CAD). You take the Cambridge IGCSE with Canadian courses alongside, then complete the Canadian Grade 12 year, and graduate with both the IGCSE certificate and the New Brunswick High School Diploma. Choose the Science or the Commerce stream.', 60, true),
  ('when-join', 'new', 'When can I join?', 'You can join in Grade 10 (a three-year programme) or in Grade 11 (a two-year programme). Two years is the minimum.', 70, true),
  ('how-long', 'new', 'How long does it take to earn the Canadian Diploma?', 'At least two years. If you join in Grade 10 you study for three years (Grades 10 to 12); if you join in Grade 11 you study for two years (Grades 11 and 12).', 80, true),
  ('assessment', 'all', 'How am I assessed?', 'Each CAN course is marked 60% on continuous assessment (assignments, end-of-chapter tests and a project) and 40% on the final examination. There are no midterm examinations.', 90, true),
  ('ielts', 'all', 'What IELTS score do I need?', 'IMAS requires IELTS band 6 or higher to graduate. The school prepares you for IELTS during the programme and arranges for you to sit the exam.', 100, true),
  ('credit-hour', 'all', 'What is a credit-hour?', 'It is how New Brunswick measures study. Each course is worth 4 credit-hours and is designed for 90 hours of teaching. You need 100 credit-hours to graduate.', 110, true),
  ('pass-mark', 'current', 'What mark do I need to pass a course?', 'You need at least 60% in every course.', 120, true),
  ('extension', 'current', 'What does “continues from Grade 10” mean?', 'The course started in Grade 10 and carries on into Grade 11. It is the same course, so it is not counted as a new subject.', 130, true),
  ('prep', 'current', 'What are Prep courses?', 'Prep courses prepare you for your Grade 12 Canadian subjects. CAN students take them in Semester 2 of Grade 11, in the Canadian Preparatory Program.', 140, true),
  ('attendance', 'current', 'Is there an attendance requirement?', 'Yes. You must keep at least 90% attendance. Below that, you may not be registered for the final examination.', 150, true),
  ('drop-subject', 'current', 'Can I drop a subject?', 'CAN students cannot drop subjects in Grades 10 and 11.', 160, true),
  ('career-plan', 'current', 'What is the Career Life Plan?', 'A personal plan for your studies and career that you build and keep up to date for the whole programme. It is a graduation requirement, and Career Pathway Design helps you develop it.', 170, true),
  ('canada-university', 'all', 'Can I study at a university in Canada?', 'Yes. The diploma is recognised by universities across Canada and worldwide. AEI’s partner universities, St. Thomas, Mount Allison and Saint Mary’s, offer tuition savings to graduates of the New Brunswick programme.', 180, true),
  ('fees', 'new', 'How much does the programme cost?', 'Please speak to our admissions team for the current fees for your entry year.', 190, true)
insert into public.announcements (id, title, body, audience, published_at, published) values
  ('student-portal-coming', 'Your Student Portal is on the way', 'Soon you will sign in with your IMAS account to see the courses you have completed, your credit-hours, your grades and your projected graduation date.', 'current', '2026-10-15', true)
